select public.prepify_load_bank('Chemistry', 13, $j$[["Organic chemistry is the study of compounds of:",["nitrogen","carbon","oxygen","sulphur"],"B",1,0,"d77b221f8e95",0],["The ability of carbon atoms to join with each other to form long chains and rings is called:",["isomerism","catenation","polymerization","hydrolysis"],"B",3,0,"46ee475fd03a",0],["Carbon forms four covalent bonds because it is:",["monovalent","divalent","trivalent","tetravalent"],"D",1,0,"e787bd64400d",0],["Which of these is NOT usually classed as an organic compound?",["Methane","Ethanol","Carbon dioxide","Glucose"],"C",3,0,"540bd5c456b2",0],["The main natural sources of organic compounds are:",["coal, petroleum, natural gas and living things","sand and rocks","sea salt and air","metals and ores"],"A",1,0,"342b7e89c22e",0],["The functional group of an alcohol is:",["–OH","–COOH","–CHO","–NH₂"],"A",3,0,"5719467b486c",0],["The functional group –COOH belongs to:",["alcohols","aldehydes","carboxylic acids","ketones"],"C",3,0,"226c43827bdc",0],["The functional group –CHO belongs to:",["ketones","aldehydes","esters","amines"],"B",3,0,"eb127fdd8f37",0],["A homologous series is a family of compounds in which each member differs from the next by:",["–CH₂–","–OH","–H₂O","–CO₂"],"A",3,0,"b11a39c32ae6",0],["Members of a homologous series have:",["the same general formula and similar chemical properties","different functional groups","identical boiling points","no carbon"],"A",3,0,"662b46219a5a",0],["Compounds with the same molecular formula but different structures are called:",["isotopes","isomers","allotropes","polymers"],"B",3,0,"d423c8a36dd1",0],["Butane (C₄H₁₀) and isobutane (C₄H₁₀) are examples of:",["isotopes","isomers","allotropes","homologues with different formulas"],"B",5,0,"729adfe8a3b3",0],["The prefix \"prop-\" in an organic name shows a chain of:",["1 carbon","2 carbons","3 carbons","4 carbons"],"C",1,0,"1cba8e974b02",0],["The prefix \"eth-\" shows a chain of:",["1 carbon","2 carbons","3 carbons","5 carbons"],"B",1,0,"51595e221a70",0],["Heating coal strongly in the absence of air is called:",["fractional distillation","destructive distillation","combustion","cracking"],"B",3,0,"18796891034b",0],["Destructive distillation of coal produces coke, coal gas and:",["coal tar","crude oil","natural gas only","sand"],"A",3,0,"d500e89a2130",0],["Crude petroleum is separated into useful parts such as petrol and diesel by:",["filtration","fractional distillation","crystallization","chromatography"],"B",3,0,"35addaefa5d5",0],["A chemist finds that a liquid turns blue litmus red and contains the –COOH group. The compound is most likely:",["an alcohol","a carboxylic acid","an alkane","an ester"],"B",3,1,"7eb5cf6cc927",0],["A formula that shows every atom and bond in a molecule is a:",["molecular formula","structural formula","empirical formula","condensed name"],"B",3,0,"43d794fae102",0],["Vinegar contains which organic compound?",["Ethanol","Ethanoic (acetic) acid","Methane","Glucose"],"B",1,0,"6b310fdf1e59",0],["Ethanol belongs to which class of compounds?",["Alcohols","Alkanes","Carboxylic acids","Ketones"],"A",1,0,"802b82936475",0],["Esters are known for their:",["pleasant fruity smells","sour taste","ability to conduct electricity","magnetic properties"],"A",3,0,"a1407758c2d9",0],["A student finds a compound that contains only carbon and hydrogen. It is a:",["carbohydrate","hydrocarbon","carboxylic acid","protein"],"B",1,1,"e7d942303b6e",0],["Why are there millions of organic compounds but far fewer inorganic ones?",["Carbon forms stable chains, rings and multiple bonds","Carbon is the most abundant element","Carbon is a metal","Organic compounds are all gases"],"A",5,0,"ec0cbab8238e",0],["Most organic compounds are:",["ionic and high-melting","covalent and have relatively low melting points","metals","insoluble in all solvents"],"B",3,0,"38865968a2c2",0],["Which of these products is made from organic compounds?",["Plastics and medicines","Glass","Table salt","Iron nails"],"A",1,0,"4be0efad8533",0],["The functional group in amines is:",["–NH₂","–OH","–COOH","–CHO"],"A",3,0,"ada8aa4a46f3",0],["A molecule has the condensed formula CH₃CH₂OH. How many carbon atoms does it contain?",["1","2","3","6"],"B",3,1,"c1acebdae081",0],["The general formula of the alcohol series (alkanols) is:",["CₙH₂ₙ₊₁OH","CₙH₂ₙ","CₙH₂ₙ₋₂","CₙH₂ₙ₊₁COOH"],"A",5,0,"9f86c25547e1",0],["In a homologous series, as the chain gets longer, the boiling point generally:",["decreases","increases","stays the same","becomes zero"],"B",5,0,"43796beba318",0],["Which group is present in every alcohol, such as methanol and ethanol?",["–OH","–COOH","–CHO","–NH₂"],"A",3,0,"5719467b486c",0],["Ethanoic acid (CH₃COOH) belongs to the class of:",["alcohols","aldehydes","carboxylic acids","ketones"],"C",3,0,"226c43827bdc",0],["Glucose and fructose both have the formula C₆H₁₂O₆ but different structures. They are:",["isotopes","isomers","allotropes","polymers"],"B",5,0,"d423c8a36dd1",0],["The prefix \"but-\" in butane shows a chain of:",["2 carbons","3 carbons","4 carbons","5 carbons"],"C",1,0,"1cba8e974b02",0],["Petrol, diesel and kerosene are obtained from crude oil by:",["filtration","fractional distillation","crystallization","chromatography"],"B",3,0,"35addaefa5d5",0],["Coke, coal gas and coal tar are produced when coal is:",["burnt in plenty of air","heated strongly without air","dissolved in water","cracked with a catalyst"],"B",3,0,"18796891034b",0],["Carbon atoms can link together to form very long chains. This property is called:",["isomerism","catenation","hydrolysis","oxidation"],"B",1,0,"46ee475fd03a",0],["Which of these is an inorganic compound?",["Ethanol","Methane","Sodium chloride","Glucose"],"C",3,0,"540bd5c456b2",0],["The pleasant smells of many fruits and perfumes come from compounds called:",["esters","alkanes","amines","acids"],"A",3,0,"a1407758c2d9",0],["How many carbon atoms are in one molecule of octane?",["9","8","10","7"],"B",1,0,"gen-chemistry-c13-carbon-count",0],["How many carbon atoms are in one molecule of propane?",["2","3","5","4"],"B",1,0,"gen-chemistry-c13-carbon-count",0],["How many carbon atoms are in one molecule of propanol?",["2","3","5","4"],"B",1,0,"gen-chemistry-c13-carbon-count",0],["How many carbon atoms are in one molecule of ethanol?",["1","2","3","4"],"B",1,0,"gen-chemistry-c13-carbon-count",0],["How many carbon atoms are in one molecule of butanol?",["5","3","4","6"],"C",1,0,"gen-chemistry-c13-carbon-count",0],["How many carbon atoms are in one molecule of methanol?",["4","1","2","3"],"B",1,0,"gen-chemistry-c13-carbon-count",0],["A compound has the molecular formula C₅H₁₂. Which statement about it is correct?",["It must contain a double bond","It is an unsaturated hydrocarbon","It belongs to the alkane homologous series","It contains a functional group"],"C",3,0,"ae9b7f1f3ca5",1],["Which formula represents an alkene rather than an alkane?",["C₄H₁₀","C₅H₁₂","C₆H₁₂","C₃H₈"],"C",3,0,"0d37bff04485",1],["An unknown hydrocarbon contains 6 carbon atoms and 14 hydrogen atoms. Its classification is:",["Alkene","Alkyne","Alkane","Aromatic compound"],"C",3,0,"a05b99e932b3",1],["Which pair belongs to the same homologous series?",["CH₄ and C₂H₄","C₂H₆ and C₃H₈","C₂H₄ and C₃H₈","C₂H₂ and C₃H₈"],"B",3,0,"55ce4f7a842a",1],["Two consecutive members of a homologous series differ by:",["CH₃","CH₂","C₂H₂","H₂"],"B",3,0,"28ec355549e1",1],["A hydrocarbon has the general formula CₙH₂ₙ₋₂. It is most likely a:",["Alkane","Alkene","Alkyne","Cycloalkane"],"C",3,0,"47ab2b66a3a0",1],["Which molecular formula would not normally represent an open-chain alkane?",["C₃H₈","C₄H₁₀","C₅H₁₂","C₆H₁₂"],"D",3,0,"8d3907213bd3",1],["If an alkane contains 7 carbon atoms, its molecular formula will be:",["C₇H₁₄","C₇H₁₆","C₇H₁₂","C₇H₈"],"B",3,0,"59a028c6649b",1],["Which condensed structural formula represents pentane?",["CH₃CH₂CH₂CH₃","CH₃CH₂CH₂CH₂CH₃","CH₃CH₂CH₃","CH₃CH₂CH₂CH₂CH₂CH₃"],"B",3,0,"5eaf24e8da7b",1],["A student writes CH₃–CH₂–CH₂–CH₃ and calls it pentane. What is the error?",["It contains a double bond","It has three carbon atoms","It has four carbon atoms and is butane","It contains a functional group"],"C",3,0,"62beaca8485d",1],["Carbon forms millions of compounds mainly because it can:",["Form ionic bonds only","Form four bonds and undergo catenation","Lose all four electrons easily","Form bonds only with hydrogen"],"B",3,0,"0009d5d9f360",1],["The ability of carbon atoms to bond with one another to form chains and rings is called:",["Isomerism","Polymerization","Catenation","Hydrogenation"],"C",3,0,"67bcfb985a7b",1],["Which arrangement represents a branched-chain compound?",["CH₃–CH₂–CH₂–CH₃","CH₃–CH₂–CH₂–CH₂–CH₃","CH₃–CH(CH₃)–CH₃","CH₃–CH₂–CH₃"],"C",3,0,"3edd39d72621",1],["An organic compound contains a continuous carbon chain with no ring. It is classified as:",["Cyclic","Acyclic","Aromatic","Heterocyclic"],"B",3,0,"2551a9084b6b",1],["Which structure represents a cyclic organic compound?",["CH₃CH₂CH₃","CH₃CH₂CH₂CH₃","A carbon chain joined to form a ring","CH₃CH(CH₃)CH₃"],"C",3,0,"85c48c9f39b4",1],["Which feature distinguishes an unsaturated hydrocarbon from a saturated one?",["Presence of carbon","Presence of hydrogen","Presence of at least one C=C or C≡C bond","Presence of C–H bonds"],"C",3,0,"9470fb36c546",1],["A compound has the structure CH₂=CH–CH₃. Which description is correct?",["Saturated three-carbon hydrocarbon","Unsaturated three-carbon hydrocarbon","Four-carbon alkane","Three-carbon alcohol"],"B",3,0,"b1c05d2076a0",1],["Which compound contains a triple bond?",["CH₄","C₂H₆","C₂H₄","C₂H₂"],"D",3,0,"ec1f5c2cf057",1],["If an alkene contains 5 carbon atoms, its formula according to CₙH₂ₙ is:",["C₅H₈","C₅H₁₀","C₅H₁₂","C₅H₆"],"B",3,0,"9719f636d2e8",1],["If an alkyne contains 6 carbon atoms, its formula according to CₙH₂ₙ₋₂ is:",["C₆H₁₄","C₆H₁₂","C₆H₁₀","C₆H₈"],"C",3,0,"d514c18c0a90",1],["Two compounds have the same molecular formula but different structural formulas. They are:",["Isotopes","Allotropes","Isomers","Homologues"],"C",3,0,"3d2cf6c4a280",1],["Which pair demonstrates structural isomerism?",["CH₄ and C₂H₆","CH₃CH₂OH and CH₃OCH₃","CH₄ and CH₄","C₂H₄ and C₂H₆"],"B",3,0,"b546685e190f",1],["The compounds CH₃CH₂OH and CH₃OCH₃ have:",["Different molecular formulas and same structure","Same molecular formula and different structures","Same molecular formula and same structure","Different molecular formulas and different structures"],"B",3,0,"3f59cfa08b21",1],["Why can two structural isomers have different properties?",["They contain different elements","They have different atomic numbers","Their atoms are arranged differently","They always have different molecular masses"],"C",3,0,"54721daaf3cb",1],["Which statement about molecular and structural formulas is correct?",["Both always show exactly the same information","Molecular formula shows arrangement of atoms","Structural formula shows how atoms are connected","Structural formula gives only the number of atoms"],"C",3,0,"e83a5691034e",1],["The group –OH attached to a carbon chain generally identifies:",["An amine","An alcohol","An aldehyde","A carboxylic acid"],"B",3,0,"a96ec63ab2e3",1],["Which compound contains a carboxyl group?",["CH₃OH","CH₃CHO","CH₃COOH","CH₃NH₂"],"C",3,0,"41ea234191cb",1],["A compound has the functional group –NH₂. It belongs to the family of:",["Alcohols","Amines","Esters","Ethers"],"B",3,0,"a7e2c9dd554b",1],["Which structure represents an ether?",["R–OH","R–COOH","R–O–R′","R–NH₂"],"C",3,0,"833250605746",1],["Which functional group is characteristic of an aldehyde?",["–OH","–COOH","–CHO","–NH₂"],"C",3,0,"9333ab79e1e0",1],["Which compound contains a ketone functional group?",["CH₃CH₂OH","CH₃COCH₃","CH₃COOH","CH₃CH₂NH₂"],"B",3,0,"517bfc4ef021",1],["The group >C=O occurring between two carbon groups is characteristic of:",["Ketones","Alcohols","Amines","Ethers"],"A",3,0,"89e0a8a17c58",1],["Which compound contains an ester linkage?",["R–OH","R–COOH","R–COO–R′","R–NH₂"],"C",3,0,"1f5dab851112",1],["Which functional group is present in ethanoic acid, CH₃COOH?",["Hydroxyl","Amino","Carbonyl only","Carboxyl"],"D",3,0,"76d79d04c0fc",1],["A compound has the structure CH₃–O–CH₃. Its functional group identifies it as:",["Ether","Alcohol","Aldehyde","Ketone"],"A",3,0,"9970e186127f",1],["Which pair contains compounds with the same functional group?",["Ethanol and ethanoic acid","Ethanol and propanol","Ethanol and ethanal","Ethanal and ethanoic acid"],"B",3,0,"6ed8d2b3f67f",1],["Two compounds belong to the same homologous series. Which property should they normally share?",["Same molecular mass","Same number of carbon atoms","Same general formula and functional group","Exactly the same physical properties"],"C",3,0,"ca50d05f6635",1],["Which change occurs when moving from one member to the next in an alkane homologous series?",["Addition of CH₄","Addition of CH₂","Removal of H₂","Addition of C₂H₄"],"B",3,0,"8d08c84ee221",1],["A student compares methane, ethane, and propane. Which observation correctly describes them?",["They have identical molecular formulas","They belong to different homologous series","Each successive member differs by CH₂","They all contain double bonds"],"C",3,0,"3658316a1e2e",1],["Which sequence is arranged correctly as consecutive members of the alkane series?",["CH₄ → C₂H₄ → C₃H₆","CH₄ → C₂H₆ → C₃H₈","CH₄ → C₂H₆ → C₃H₆","CH₄ → C₂H₂ → C₃H₄"],"B",3,0,"0c80cc915bdb",1],["Which carbon-containing compound is generally classified as inorganic despite containing carbon?",["Methane","Ethanol","Carbon dioxide","Glucose"],"C",3,0,"9373728560de",1],["Which statement gives the more useful definition of organic compounds at this level?",["All compounds containing carbon","Only compounds containing hydrogen","Hydrocarbons and their derivatives","Only compounds found in living organisms"],"C",3,0,"cd55987f0abc",1],["Which substance is not considered an organic compound?",["C₂H₅OH","CH₄","CO₂","C₆H₁₂O₆"],"C",3,0,"7ffb9606e1ce",1],["A researcher finds a compound containing carbon, hydrogen, and oxygen. Which conclusion is safest?",["It must be a hydrocarbon","It cannot be organic","It may be an organic compound, depending on its structure","It must be an alkane"],"C",3,0,"7fc55fa95313",1],["Which combination correctly matches the compound with its family?",["CH₃OH — amine","CH₃COOH — carboxylic acid","CH₃NH₂ — alcohol","CH₃OCH₃ — aldehyde"],"B",3,0,"893cd501509f",1],["An unknown compound has formula C₄H₁₀. Which statement is most appropriate?",["It can be an alkane","It must be an alkene","It must contain a triple bond","It contains a carboxyl group"],"A",3,0,"b88a2d4897f5",1],["An unknown hydrocarbon has formula C₄H₈ and is described as an open-chain compound. Which classification is most consistent?",["Alkane","Alkene","Alkyne","Alcohol"],"B",3,0,"e89b267e91c9",1],["An unknown hydrocarbon has formula C₄H₆ and is an open-chain compound containing one triple bond. It belongs to:",["Alkanes","Alkenes","Alkynes","Alcohols"],"C",3,0,"bfe4fe4b0f85",1],["Which sequence correctly represents increasing carbon-chain length within one alkane homologous series?",["Ethane → methane → propane","Methane → ethane → propane → butane","Methane → propane → ethane → butane","Ethane → propane → methane → pentane"],"B",3,0,"71195e8e75bc",1],["A student is given the following compounds:\nP = CH₃CH₂OH\nQ = CH₃OCH₃\nR = CH₃COOH\nS = CH₃CH₂CH₃\nWhich statement is correct?",["P and Q are functional-group isomers","P and R have the same functional group","Q and S belong to the same functional group family","R is a hydrocarbon"],"A",3,0,"ba9448768660",1],["A student studies a group of organic compounds: methane (CH₄), ethane (C₂H₆), propane (C₃H₈), and butane (C₄H₁₀). He observes that each compound differs by one carbon atom and shows similar chemical behavior.\n\nIf the student wants to continue the study with the next compound in this exact same group, what should its chemical formula be?",["C₅H₁₀","C₄H₁₂","C₅H₁₂","C₆H₁₄"],"C",5,1,"0e39eb7358c0",1],["A student studies a group of organic compounds: methane (CH₄), ethane (C₂H₆), propane (C₃H₈), and butane (C₄H₁₀). He observes that each compound differs by one carbon atom and shows similar chemical behavior.\n\nWhat is the common difference between successive members?",["CH₂ group","CH₃ group","C₂H₄ group","H₂ group"],"A",5,1,"bdec16c637dc",1],["A student studies a group of organic compounds: methane (CH₄), ethane (C₂H₆), propane (C₃H₈), and butane (C₄H₁₀). He observes that each compound differs by one carbon atom and shows similar chemical behavior.\n\nWhy do these compounds show similar chemical properties?",["Same molecular mass","Same functional group","Same number of atoms","Same physical state"],"B",5,1,"5a72d529aea2",1],["A student studies a group of organic compounds: methane (CH₄), ethane (C₂H₆), propane (C₃H₈), and butane (C₄H₁₀). He observes that each compound differs by one carbon atom and shows similar chemical behavior.\n\nWhich property shows a gradual change in a homologous series?",["Chemical reactivity","Functional group","Boiling point","Type of bonding"],"C",5,1,"1f0559e58fce",1],["The labels have fallen off four bottles in the school store. The stock list gives the condensed formula for each bottle. Bottle P is CH₃CH₂OH. Bottle Q is CH₃OCH₃. Bottle R is CH₃COOH. Bottle S is CH₃CHO. The table shows the same formulas.\n\nWhich functional group does bottle R contain?",["-OH","-CHO","-COOH","-O-"],"C",5,1,"a76487cb664f",1],["The labels have fallen off four bottles in the school store. The stock list gives the condensed formula for each bottle. Bottle P is CH₃CH₂OH. Bottle Q is CH₃OCH₃. Bottle R is CH₃COOH. Bottle S is CH₃CHO. The table shows the same formulas.\n\nWhich bottle holds an aldehyde?",["P","Q","R","S"],"D",5,1,"62f98c52d40d",1],["The labels have fallen off four bottles in the school store. The stock list gives the condensed formula for each bottle. Bottle P is CH₃CH₂OH. Bottle Q is CH₃OCH₃. Bottle R is CH₃COOH. Bottle S is CH₃CHO. The table shows the same formulas.\n\nCount the atoms in bottles P and Q. What is true about these two compounds?",["Same atoms, joined in a different way, so they are isomers","They are the same compound written in two ways","They are next to each other in a homologous series","They have different numbers of carbon atoms"],"A",5,1,"ee4cff114073",1],["The labels have fallen off four bottles in the school store. The stock list gives the condensed formula for each bottle. Bottle P is CH₃CH₂OH. Bottle Q is CH₃OCH₃. Bottle R is CH₃COOH. Bottle S is CH₃CHO. The table shows the same formulas.\n\nBottles P and Q have the same atoms, but they do not behave the same way. Why?",["They are kept in different places","They have different functional groups","One of them has more oxygen atoms","They have different molecular masses"],"B",5,1,"78f50fecbc39",1],["A chemistry teacher gives four compounds to a student:\n• P: CH₃–CH₂–CH₃\n• Q: CH₂=CH–CH₃\n• R: CH₃–CH₂–CH₂–CH₃\n• S: CH₃–CH(CH₃)–CH₃\nThe student must identify their structures and relationships. The teacher reminds the class that alkanes have the general formula CₙH₂ₙ₊₂, while compounds containing carbon-carbon multiple bonds are unsaturated.\n\nWhich pair represents compounds belonging to the same homologous series?",["P and Q","P and R","Q and R","Q and S"],"B",5,1,"64122f055d5e",1],["A chemistry teacher gives four compounds to a student:\n• P: CH₃–CH₂–CH₃\n• Q: CH₂=CH–CH₃\n• R: CH₃–CH₂–CH₂–CH₃\n• S: CH₃–CH(CH₃)–CH₃\nThe student must identify their structures and relationships. The teacher reminds the class that alkanes have the general formula CₙH₂ₙ₊₂, while compounds containing carbon-carbon multiple bonds are unsaturated.\n\nWhich statement correctly compares R and S?",["They have different molecular formulas and are different compounds","They have the same molecular formula but different structural arrangements","They belong to different homologous series","R is unsaturated while S is saturated"],"B",5,1,"414fcbc4c852",1],["A chemistry teacher gives four compounds to a student:\n• P: CH₃–CH₂–CH₃\n• Q: CH₂=CH–CH₃\n• R: CH₃–CH₂–CH₂–CH₃\n• S: CH₃–CH(CH₃)–CH₃\nThe student must identify their structures and relationships. The teacher reminds the class that alkanes have the general formula CₙH₂ₙ₊₂, while compounds containing carbon-carbon multiple bonds are unsaturated.\n\nWhich compound contains a carbon-carbon double bond?",["P","Q","R","S"],"B",5,1,"cfc05079b320",1],["A chemistry teacher gives four compounds to a student:\n• P: CH₃–CH₂–CH₃\n• Q: CH₂=CH–CH₃\n• R: CH₃–CH₂–CH₂–CH₃\n• S: CH₃–CH(CH₃)–CH₃\nThe student must identify their structures and relationships. The teacher reminds the class that alkanes have the general formula CₙH₂ₙ₊₂, while compounds containing carbon-carbon multiple bonds are unsaturated.\n\nIf the next member after R is added to the same alkane homologous series, its molecular formula will be:",["C₄H₈","C₅H₁₀","C₅H₁₂","C₆H₁₄"],"C",5,1,"9e8d439fa0e7",1],["A chemistry teacher gives four compounds to a student:\n• P: CH₃–CH₂–CH₃\n• Q: CH₂=CH–CH₃\n• R: CH₃–CH₂–CH₂–CH₃\n• S: CH₃–CH(CH₃)–CH₃\nThe student must identify their structures and relationships. The teacher reminds the class that alkanes have the general formula CₙH₂ₙ₊₂, while compounds containing carbon-carbon multiple bonds are unsaturated.\n\nWhich conclusion best explains why R and S can have different properties despite having the same molecular formula?",["Their carbon atoms have different atomic numbers","Their structural arrangements are different","They contain different numbers of elements","One must contain a double bond"],"B",5,1,"4e66cb36614c",1],["A laboratory technician labels four organic compounds:\n• A: CH₃CH₂OH\n• B: CH₃CHO\n• C: CH₃COCH₃\n• D: CH₃COOH\nThe technician asks students to identify each compound from its functional group. In organic compounds, the functional group is the atom or group of atoms responsible for characteristic properties.\n\nWhich compound contains the hydroxyl functional group characteristic of alcohols?",["A","B","C","D"],"A",5,1,"b2f78ec64cd7",1],["A laboratory technician labels four organic compounds:\n• A: CH₃CH₂OH\n• B: CH₃CHO\n• C: CH₃COCH₃\n• D: CH₃COOH\nThe technician asks students to identify each compound from its functional group. In organic compounds, the functional group is the atom or group of atoms responsible for characteristic properties.\n\nWhich pair contains compounds having a carbonyl group, but belonging to different functional-group families?",["A and D","B and C","A and B","C and D"],"B",5,1,"a466d0484a97",1],["A laboratory technician labels four organic compounds:\n• A: CH₃CH₂OH\n• B: CH₃CHO\n• C: CH₃COCH₃\n• D: CH₃COOH\nThe technician asks students to identify each compound from its functional group. In organic compounds, the functional group is the atom or group of atoms responsible for characteristic properties.\n\nWhat distinguishes B from C?",["B has no oxygen, while C contains oxygen","B has the carbonyl group at the end of the carbon chain, while C has it between carbon atoms","B is an alcohol, while C is an acid","B is saturated, while C is unsaturated"],"B",5,1,"a2f50e3cd907",1],["A laboratory technician labels four organic compounds:\n• A: CH₃CH₂OH\n• B: CH₃CHO\n• C: CH₃COCH₃\n• D: CH₃COOH\nThe technician asks students to identify each compound from its functional group. In organic compounds, the functional group is the atom or group of atoms responsible for characteristic properties.\n\nIf the hydrogen attached to the carboxyl group of D is removed, which part of the molecule has been affected?",["Amino group","Hydroxyl group only","Carboxyl functional group","Carbon-carbon backbone only"],"C",5,1,"82b5a56d2365",1],["A laboratory technician labels four organic compounds:\n• A: CH₃CH₂OH\n• B: CH₃CHO\n• C: CH₃COCH₃\n• D: CH₃COOH\nThe technician asks students to identify each compound from its functional group. In organic compounds, the functional group is the atom or group of atoms responsible for characteristic properties.\n\nWhich sequence correctly identifies A, B, C and D respectively?",["Alcohol, aldehyde, ketone, carboxylic acid","Alcohol, ketone, aldehyde, carboxylic acid","Ether, aldehyde, ketone, alcohol","Alcohol, amine, ketone, ester"],"A",5,1,"d63279c84fe9",1]]$j$::jsonb, true);
